import{_ as n,o as a,c as t,a3 as s}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Dependency Scanning","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Dependency Scanning | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/design/dependency-scanning"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/design/dependency-scanning"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/design/dependency-scanning"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/design/dependency-scanning"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/design/dependency-scanning"}]]},"headers":[],"relativePath":"clice/design/dependency-scanning.md","filePath":"en/clice/design/dependency-scanning.md","lastUpdated":1794738697000}'),i={name:"clice/design/dependency-scanning.md"};function o(r,e,d,c,h,l){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="dependency-scanning" tabindex="-1">Dependency Scanning <a class="header-anchor" href="#dependency-scanning" aria-label="Permalink to &quot;Dependency Scanning&quot;">​</a></h1><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>A language server needs the include relationships of the whole project from the start:</p><ul><li><strong>Headers need hosts.</strong> A header has no entry in the compilation database; to compile it, clice needs a source that includes it — the reverse of the include graph.</li><li><strong>Modules need a map.</strong> Building a module needs to know which file declares each module name and what each file imports.</li></ul><p>Exact include relationships take the full preprocessor — every macro expanded, every condition evaluated — and on tens of thousands of files that takes minutes. clangd builds its include graph as its background index compiles files, so until indexing finishes, which can take tens of minutes, a header opened may find no host and show false errors. clice runs a fast scanner of its own instead, and has a usable graph seconds after startup.</p><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;Design&quot;">​</a></h2><h3 id="a-superset-shared-by-every-includer" tabindex="-1">A Superset, Shared by Every Includer <a class="header-anchor" href="#a-superset-shared-by-every-includer" aria-label="Permalink to &quot;A Superset, Shared by Every Includer&quot;">​</a></h3><p>The scanner does not preprocess. Without macros or conditions evaluated, what a file includes no longer depends on who includes it, so each file is scanned once and its result shared by every includer: the work is the number of distinct files, not the number of (source, header) pairs. The price is that both branches of every <code>#if</code> count, giving a superset of the real include relationships. For what the graph is used for, a superset is safe: host lookup may find more candidates but never misses the real one — and each candidate is checked against its real compile before it hosts a header.</p><h3 id="why-it-is-fast" tabindex="-1">Why It Is Fast <a class="header-anchor" href="#why-it-is-fast" aria-label="Permalink to &quot;Why It Is Fast&quot;">​</a></h3><ul><li><strong>Directive scanning.</strong> Clang&#39;s dependency directive scanner reads only the directive lines of a file, microseconds per file, and yields the raw include names (<code>&quot;foo.h&quot;</code>, <code>&lt;vector&gt;</code>).</li><li><strong>Cached resolution.</strong> Include names are resolved against cached directory listings rather than by a stat of each candidate path, and an angled include is resolved once per configuration and name.</li><li><strong>Waves.</strong> The scan starts with every translation unit of the build and the files their commands force in (<code>-include</code>, <code>-imacros</code>), resolves what they include, scans the headers newly found, and repeats until nothing new turns up. While one wave resolves, the next one&#39;s files are already being read.</li></ul><h3 id="the-graph" tabindex="-1">The Graph <a class="header-anchor" href="#the-graph" aria-label="Permalink to &quot;The Graph&quot;">​</a></h3><ul><li><strong>Forward edges</strong>: what each file includes. A unit is resolved under each of its commands, since search paths differ between them; a header under the first command that reaches it.</li><li><strong>Reverse edges</strong>, built in bulk, for climbing from a header to the units that include it.</li><li><strong>Forced includes</strong> kept apart from the include edges, as no directive in the source names them; host lookup climbs them too.</li><li><strong>Module names</strong> mapped to the units declaring them, interfaces and partitions. A module declaration the directive scanner cannot read — one inside an <code>#if</code> — makes the preprocessor run on that file alone, up to the declaration.</li></ul><p>Each file&#39;s scan is kept against its content version and reused while the content holds. A changed file is rescanned and resolved as the startup scan reached it, which replaces its edges and scans the headers it newly reaches.</p><h3 id="exact-answers-where-needed" tabindex="-1">Exact Answers Where Needed <a class="header-anchor" href="#exact-answers-where-needed" aria-label="Permalink to &quot;Exact Answers Where Needed&quot;">​</a></h3><p>Where an exact answer matters — the modules a unit imports, before each of its builds (see <a href="./task-graph">Compile Task Graph</a>) — the preprocessor runs on that unit. The fast scan says where that can be skipped: it records which files hold module syntax, and a unit reaching none of them through its includes imports nothing, since no macro can produce an <code>import</code>.</p><p>The background index compiles every unit with the full preprocessor and records the exact include trees in the index, which host lookup reads to check where a candidate&#39;s compile really enters a header. The fast scan&#39;s graph stays what finds the candidates.</p><h2 id="design-decisions" tabindex="-1">Design Decisions <a class="header-anchor" href="#design-decisions" aria-label="Permalink to &quot;Design Decisions&quot;">​</a></h2><ul><li><strong>Why a superset instead of exact results?</strong> Exact results take minutes; the superset takes seconds and misses no host.</li><li><strong>Why not wait for the background index?</strong> Headers would be wrong for as long as indexing runs — tens of minutes on a big project. The fast scan gives a usable graph at once; the index refines it.</li><li><strong>Why waves?</strong> Headers are not in the database: they are found only by resolving what the sources include, and each wave&#39;s results name the next wave&#39;s files.</li></ul><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li><strong>Macro includes</strong> (<code>#include MACRO_NAME</code>) are not resolved by the scan; the compile handles them.</li><li><strong>Both branches of every condition count</strong>, so the graph is larger than any one compile&#39;s, and a file can look related to one it never includes.</li><li><strong>A header is resolved under the first command reaching it.</strong> A header two units reach through different include paths gets no host from the second until that unit is indexed.</li><li><strong>The scan reads the disk.</strong> An <code>#include</code> typed in an open buffer adds no edge until it is saved.</li></ul>',20)])])}const g=n(i,[["render",o]]);export{p as __pageData,g as default};
